# search conceptually for exact output pattern in demo 3 sections under dihedral transforms
import numpy as np
out3={(0,2),(1,0),(1,1),(2,2)}
p1={(5,4),(5,6),(6,0),(6,5),(6,7),(6,9),(7,5),(9,5),(9,9)}
p2={(1,2),(1,5),(4,5),(5,2),(6,0),(6,7),(6,9),(7,5),(8,2),(9,2),(9,5),(9,9),(10,1),(10,3)}
def dihedral(s):
 out=[]
 for k in range(4):
  a={(r,c) for r,c in s}
  for _ in range(k): a={(c,-r) for r,c in a}
  out.append(a);out.append({(r,-c) for r,c in a})
 return out
def fits(s, pts):
 for shape in dihedral(s):
  mr=min(r for r,c in shape);mc=min(c for r,c in shape)
  norm={(r-mr,c-mc) for r,c in shape}
  for pr,pc in pts:
   if all((pr+r,pc+c) in pts for r,c in norm): return (True,norm,(pr,pc))
 return False
fits(out3,p1),fits(out3,p2)

sA={(5,4),(5,6),(6,5),(7,5)}
sB={(8,2),(9,2),(10,1),(10,3)}
def normalize(s):
 mr=min(r for r,c in s);mc=min(c for r,c in s);return frozenset((r-mr,c-mc) for r,c in s)
normalize(sA), normalize(sB), [normalize(x) for x in dihedral(out3)]

from itertools import combinations
pts={(2,1),(2,3),(4,6),(4,13),(5,3),(6,6),(6,7),(7,1),(7,5),(7,6),(8,6),(8,7),(8,13),(10,6),(11,3),(11,8),(13,8),(13,13)}
def canon(s):
 variants=[]
 for a in dihedral(s): variants.append(tuple(sorted(normalize(a))))
 return min(variants)
for k in (3,4,5):
 counts={}
 for sub in combinations(pts,k):
  counts[canon(sub)]=counts.get(canon(sub),0)+1
 print(k, sorted(counts.items(), key=lambda x:-x[1])[:8])
